<script setup lang="ts">
import { nextTick,onBeforeUnmount,onMounted,ref } from 'vue';import { Graph } from '@antv/g6';
import { request,errorText,date } from '../api';import type { Topology } from '../types';
const data=ref<Topology>({nodes:[],links:[],observations:[],evpnRoutes:[],warnings:[],desiredRevision:'0'});const busy=ref(false);const error=ref('');const filter=ref('');const container=ref<HTMLElement>();let graph:Graph|undefined;let active=new AbortController();let generation=0;
async function render(){await nextTick();graph?.destroy();graph=undefined;if(!container.value||!data.value.nodes.length)return;const colors:Record<string,string>={node:'#0f766e',tenant:'#1d4ed8',network:'#7c3aed',host:'#c2410c',vtep:'#0891b2'};graph=new Graph({container:container.value,width:container.value.clientWidth,height:480,autoFit:'view',data:{nodes:data.value.nodes.map(n=>({id:n.id,data:{label:n.label,kind:n.kind},style:{fill:colors[n.kind]||'#475569',labelText:n.label||n.id}})),edges:data.value.links.map((e,i)=>({id:`e${i}`,source:e.source,target:e.target,style:{labelText:e.kind,stroke:e.origin==='observed'?'#0f766e':'#94a3b8'}}))},node:{style:{size:28,labelPlacement:'bottom',labelFontSize:11,labelFill:'#334155'}},edge:{style:{labelFontSize:9}},layout:{type:'dagre',rankdir:'LR',ranksep:80,nodesep:30},behaviors:['drag-canvas','zoom-canvas','drag-element']});await graph.render();}
async function load(refresh=false){active.abort();active=new AbortController();const signal=active.signal;const current=++generation;busy.value=true;error.value='';const query=new URLSearchParams({refresh:String(refresh)});for(const id of filter.value.split(',').map(s=>s.trim()).filter(Boolean))query.append('nodeId',id);try{const result=await request<Topology>(`/topology?${query}`,{signal});if(current!==generation)return;data.value=result;await render();}catch(e){if(!signal.aborted)error.value=errorText(e);}finally{if(current===generation)busy.value=false;}}
onMounted(()=>load());onBeforeUnmount(()=>{generation++;active.abort();graph?.destroy();graph=undefined;});
</script>
<template><section class="sdn-page"><div class="page-head"><div><h1>网络拓扑</h1><p class="subtitle">配置关系与 EVPN 观测 · 期望版本 {{data.desiredRevision}}。Type-2/3 不等同于物理布线。</p></div><el-button :loading="busy" @click="load(true)">采集最新状态</el-button></div><el-alert v-if="error" type="error" :title="error" :closable="false"/><el-alert v-for="warning in data.warnings" :key="warning" :title="warning" type="warning" :closable="false"/><div class="panel"><div class="toolbar"><el-input v-model="filter" placeholder="节点 ID 范围，以逗号分隔；留空查询当前全局视图" aria-label="拓扑节点范围" style="max-width:620px"/><el-button :disabled="busy" @click="load(false)">查询缓存</el-button></div><div v-show="data.nodes.length" ref="container" class="graph"/><el-empty v-if="!data.nodes.length" description="暂无拓扑数据，可先配置网络或采集节点状态"/><p class="subtitle" style="margin-top:12px">{{data.nodes.length}} 个图节点 · {{data.links.length}} 条关系 · 图关系保留 Controller 提供的来源。</p></div><div class="panel"><h2>观测新鲜度</h2><el-table :data="data.observations"><el-table-column prop="nodeId" label="节点 ID" min-width="220"/><el-table-column label="采集时间" min-width="180"><template #default="{row}">{{date(row.collectedUnixMs)}}</template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="row.stale?'warning':'success'">{{row.stale?'已过期':'已采集'}}</el-tag></template></el-table-column><el-table-column prop="error" label="采集错误" min-width="200"/></el-table></div><div class="panel"><h2>EVPN 路由 · {{data.evpnRoutes.length}} 条</h2><el-table :data="data.evpnRoutes" max-height="500" empty-text="尚无 EVPN 观测"><el-table-column prop="type" label="Type" width="70"/><el-table-column prop="rd" label="RD" min-width="170"/><el-table-column prop="mac" label="MAC" min-width="165"/><el-table-column prop="ip" label="IP" min-width="140"/><el-table-column label="下一跳" min-width="150"><template #default="{row}">{{row.nextHops?.join(', ')}}</template></el-table-column><el-table-column prop="sourceNode" label="来源节点" min-width="220"/></el-table></div></section></template>
